+#[test]
+fn offset2d_do_not_touch_keeps_full_tool_clear_of_protected_face_and_edge() {
+    let (dir, mut c, plate_top, tower_top_face, tower_edge, tower_vert) = setup_plate_and_tower("offset2d");
+    let added = c.ok("add_operation", json!({
